package com.lexorion.workforce.api;import static com.lexorion.workforce.api.ResourceDtos.*;import com.lexorion.workforce.service.ReferenceService;import jakarta.validation.Valid;import java.net.URI;import java.util.List;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/workforce/departments") @PreAuthorize("hasRole('ADMIN')") public class DepartmentController {private final ReferenceService service;public DepartmentController(ReferenceService s){service=s;}@GetMapping public List<Reference> list(@RequestParam(required=false)Boolean active,@RequestParam(required=false)String parentDepartmentKey,@RequestParam(required=false)String search){return service.departments(active,parentDepartmentKey,search);}@PostMapping public ResponseEntity<Reference> create(@Valid@RequestBody CreateReference r){var v=service.createDepartment(r);return ResponseEntity.created(URI.create("/api/workforce/departments/"+v.key())).body(v);}@PatchMapping("/{key}")public Reference update(@PathVariable String key,@Valid@RequestBody UpdateReference r){return service.updateDepartment(key,r);}}
